import{_ as a,a as t,c as r,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"网络排障：变更窗口、路径证据与 TLS","description":"集中呈现 DNS 路由变更、PMTU、抓包和 HTTP/TLS 诊断。","frontmatter":{"title":"网络排障：变更窗口、路径证据与 TLS","description":"集中呈现 DNS 路由变更、PMTU、抓包和 HTTP/TLS 诊断。","showdocs":{"topics":[{"id":"network","title":"网络配置与诊断","link":"/topics/network/"},{"id":"security","title":"身份与权限","link":"/topics/security/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"网络：分层、寻址与证据","summary":"集中呈现 DNS 路由变更、PMTU、抓包和 HTTP/TLS 诊断。","status":"active","related":[{"title":"Linux 排障：权限、服务、空间与远程登录","link":"/systems/linux/troubleshooting","kind":"排错","scope":"general","audience":"general"},{"title":"Linux 排障：权限、服务、空间与远程登录 · 服务变更失败的恢复与复盘","link":"/systems/linux/troubleshooting-part-02","kind":"排错","scope":"general","audience":"general"},{"title":"Linux 排障：权限、服务、空间与远程登录 · 权限、服务与资源故障定位至SSH 登录被拒绝","link":"/systems/linux/troubleshooting-part-01","kind":"排错","scope":"general","audience":"general"},{"title":"网络：离线推演 DNS 与双向路径证据","link":"/systems/network-remote/network/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"网络配置与诊断 操作与命令","link":"/systems/network-remote/network/plus/ecosystem/network-general-general","kind":"命令与对象入口","scope":"general","audience":"general"}],"prev":{"text":"网络：离线推演 DNS 与双向路径证据","link":"/systems/network-remote/network/plus/practice/application"},"next":{"text":"网络：能 ping 但业务连接失败的复盘","link":"/systems/network-remote/network/pro/review/review"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"网络：离线推演 DNS 与双向路径证据","link":"/systems/network-remote/network/plus/practice/application"},"next":{"text":"网络：能 ping 但业务连接失败的复盘","link":"/systems/network-remote/network/pro/review/review"}},"headers":[],"relativePath":"systems/network-remote/network/troubleshooting.md","filePath":"systems/network-remote/network/troubleshooting.md"}'),i={name:"systems/network-remote/network/troubleshooting.md"};function n(o,e,l,p,c,h){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="网络排障-变更窗口、路径证据与-tls" tabindex="-1">网络排障：变更窗口、路径证据与 TLS <a class="header-anchor" href="#网络排障-变更窗口、路径证据与-tls" aria-label="Permalink to &quot;网络排障：变更窗口、路径证据与 TLS&quot;">​</a></h1><h2 id="part-1" tabindex="-1">网络变更、证据留存与恢复 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;网络变更、证据留存与恢复 {#part-1}&quot;">​</a></h2><p>本篇用于日常变更与恢复：操作前保存当前配置和资源对应关系，操作后检查业务结果，达到回退条件时按已确认的顺序恢复。</p><h3 id="part-1-change" tabindex="-1">DNS与路由变更窗口 <a class="header-anchor" href="#part-1-change" aria-label="Permalink to &quot;DNS与路由变更窗口 {#part-1-change}&quot;">​</a></h3><p>网络变更窗口应记录旧值、影响范围、观察点与回退触发条件。DNS先降低TTL仍需等待此前缓存到期；路由先核对管理通道回程，再分批生效。每次只改变一个可归因变量，保留带时间的前后快照。离线推演通过不能证明真实链路可用。</p><h3 id="part-1-privacy" tabindex="-1">抓包保留与脱敏 <a class="header-anchor" href="#part-1-privacy" aria-label="Permalink to &quot;抓包保留与脱敏 {#part-1-privacy}&quot;">​</a></h3><p>抓包脱敏应覆盖凭据、Cookie、DNS查询和内部拓扑；只遮住截图中的IP并没有清除原始文件。先限定接口、主机、时间与文件大小，再按授权保留期限删除材料。向协作者提供最少字段，保留必要的序号、方向和时序关系，避免因脱敏破坏诊断证据。</p><h3 id="part-1-exercise" tabindex="-1">练习与参考解答 <a class="header-anchor" href="#part-1-exercise" aria-label="Permalink to &quot;练习与参考解答 {#part-1-exercise}&quot;">​</a></h3><p>练习：DNS记录原TTL为3600秒，10:00才降到60秒，10:01计划切换；09:59已缓存旧记录的客户端一定在10:02更新吗？列出切换和回退清单中的具体对象。</p><details class="details custom-block"><summary>参考解答</summary><p>不能保证，该客户端可能按原3600秒保留到接近10:59。清单应保存旧/新记录、解析器与权威观察点、原TTL窗口、负责人和回退触发条件；同时检查管理通道的地址与返回路由。回退权威记录也不能立即清空所有递归缓存。</p></details><h2 id="part-2" tabindex="-1">解析失败、拒绝与超时定位 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;解析失败、拒绝与超时定位 {#part-2}&quot;">​</a></h2><p>定位故障时先记录时间、目标和最近变更，再沿本篇的对象链检查。保留原始错误与状态；每次只改变一个已找到证据的条件，并复测原始症状。</p><h3 id="part-2-sequence" tabindex="-1">从现象到最小证据 <a class="header-anchor" href="#part-2-sequence" aria-label="Permalink to &quot;从现象到最小证据 {#part-2-sequence}&quot;">​</a></h3><p>超时排查先确认目标名字、解析结果与目标端口，再查本机源地址、路由、链路与回程。DNS成功后连接失败，不能继续把问题归咎于解析。用两端同时刻的证据判断SYN是否到达、响应是否返回；没有抓到包只能说明当前观察点没看到，不能断言全网无包。</p><h3 id="part-2-mtu" tabindex="-1">大包失败与PMTU <a class="header-anchor" href="#part-2-mtu" aria-label="Permalink to &quot;大包失败与PMTU {#part-2-mtu}&quot;">​</a></h3><p>PMTU问题常表现为小包可达、大负载卡住。路径MTU小于发送大小且必要ICMP消息被过滤，可能形成黑洞；隧道封装还会增加开销。不要以一次ping成功证明大流量正常，也不要直接全局降低MTU。先确认封装、接口和ICMP反馈，再在隔离环境逐段推演。</p><h3 id="part-2-exercise" tabindex="-1">练习与参考解答 <a class="header-anchor" href="#part-2-exercise" aria-label="Permalink to &quot;练习与参考解答 {#part-2-exercise}&quot;">​</a></h3><p>练习：材料：名字解析正常，小请求成功，经隧道的大响应反复超时。是否可以据此关闭所有防火墙？下一步至少核对哪两项证据？</p><details class="details custom-block"><summary>参考解答</summary><p>不能。小请求不证明路径支持更大的报文，隧道封装可能降低有效MTU，必要的ICMP反馈被过滤也可能导致黑洞。先核对隧道接口/封装开销与两端可用MTU，再核对相关ICMP反馈及大报文的发送/重传时间；仍需排除应用超时，不能仅凭模式断言PMTU故障。</p></details><h2 id="part-3" tabindex="-1">HTTPS 证书校验失败 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;HTTPS 证书校验失败 {#part-3}&quot;">​</a></h2><p>检查域名、证书链、有效期和客户端信任库。</p><p>证书校验失败意味着客户端无法确认对端身份。排查时保留校验，不使用 curl -k 或忽略证书错误作为最终修复。</p><h3 id="part-3-排查步骤" tabindex="-1">排查步骤 <a class="header-anchor" href="#part-3-排查步骤" aria-label="Permalink to &quot;排查步骤 {#part-3-排查步骤}&quot;">​</a></h3><h4 id="part-3-_1-获取客户端校验错误" tabindex="-1">1. 获取客户端校验错误 <a class="header-anchor" href="#part-3-_1-获取客户端校验错误" aria-label="Permalink to &quot;1. 获取客户端校验错误 {#part-3-_1-获取客户端校验错误}&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>curl -vI https://&lt;host&gt;/</span></span></code></pre></div><p><strong>预期结果:</strong> 输出显示连接域名、证书问题及 HTTP 是否实际建立。</p><h4 id="part-3-_2-查看服务端证书链" tabindex="-1">2. 查看服务端证书链 <a class="header-anchor" href="#part-3-_2-查看服务端证书链" aria-label="Permalink to &quot;2. 查看服务端证书链 {#part-3-_2-查看服务端证书链}&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>openssl s_client -connect &lt;host&gt;:443 -servername &lt;host&gt; -verify_hostname &lt;host&gt; -verify_return_error</span></span></code></pre></div><p><strong>预期结果:</strong> 检查证书主题、签发者与 verify return code；SNI 和预期校验名称使用同一域名；<code>-servername</code> 只选择服务端证书，不能代替 <code>-verify_hostname</code>。</p><h4 id="part-3-_3-核对客户端时间" tabindex="-1">3. 核对客户端时间 <a class="header-anchor" href="#part-3-_3-核对客户端时间" aria-label="Permalink to &quot;3. 核对客户端时间 {#part-3-_3-核对客户端时间}&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>date -u</span></span></code></pre></div><p><strong>预期结果:</strong> 系统时间合理；若时间正确，继续核对证书有效期、域名与 CA 链。</p><h3 id="part-3-常见报错" tabindex="-1">常见报错 <a class="header-anchor" href="#part-3-常见报错" aria-label="Permalink to &quot;常见报错 {#part-3-常见报错}&quot;">​</a></h3><h4 id="part-3-certificate-has-expired" tabindex="-1">certificate has expired <a class="header-anchor" href="#part-3-certificate-has-expired" aria-label="Permalink to &quot;certificate has expired {#part-3-certificate-has-expired}&quot;">​</a></h4><p><strong>原因:</strong> 证书过期或客户端时间错误。</p><p><strong>处理方式:</strong> 先核对时间，再由证书管理方续期并部署完整证书链。</p><h4 id="part-3-unable-to-get-local-issuer-certificate" tabindex="-1">unable to get local issuer certificate <a class="header-anchor" href="#part-3-unable-to-get-local-issuer-certificate" aria-label="Permalink to &quot;unable to get local issuer certificate {#part-3-unable-to-get-local-issuer-certificate}&quot;">​</a></h4><p><strong>原因:</strong> 中间证书缺失，或客户端不信任签发 CA。</p><p><strong>处理方式:</strong> 核对服务端提供的链及客户端信任库；不要关闭验证。</p><h3 id="part-3-相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#part-3-相关文档" aria-label="Permalink to &quot;相关文档 {#part-3-相关文档}&quot;">​</a></h3><ul><li><a href="/systems/network-remote/network/plus/ecosystem/network-general-general#entry-curl-7baf5c5d18">curl</a></li></ul><h3 id="part-3-官方资料" tabindex="-1">官方资料 <a class="header-anchor" href="#part-3-官方资料" aria-label="Permalink to &quot;官方资料 {#part-3-官方资料}&quot;">​</a></h3><ul><li><a href="https://curl.se/docs/sslcerts.html" target="_blank" rel="noopener noreferrer">https://curl.se/docs/sslcerts.html</a></li><li><a href="https://docs.openssl.org/master/man1/openssl-s_client/" target="_blank" rel="noopener noreferrer">https://docs.openssl.org/master/man1/openssl-s_client/</a></li></ul>',43)])])}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
